const raw = $input.first()?.json ?? {};

function clean(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonical(value) {
  return clean(value)
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/[إأآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function toBoolean(value) {
  if (value === true) return true;

  const normalized = canonical(value);

  return [
    'true',
    'yes',
    'oui',
    'نعم',
    'اوافق',
    'موافق'
  ].includes(normalized);
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
    .test(clean(value));
}

function isFullName(value) {
  const text = clean(value);

  if (
    text.length < 3 ||
    text.length > 100 ||
    isUuid(text) ||
    !/\p{L}/u.test(text)
  ) {
    return false;
  }

  const words = text
    .split(/\s+/)
    .filter(word => /\p{L}{2,}/u.test(word));

  return words.length >= 2;
}

function isNormalText(value, min = 2, max = 120) {
  const text = clean(value);

  return (
    text.length >= min &&
    text.length <= max &&
    /\p{L}/u.test(text) &&
    !isUuid(text)
  );
}

function isValidEmail(value) {
  const email = clean(value).toLowerCase();

  if (
    !email ||
    email.includes(' ') ||
    email.startsWith('.') ||
    email.endsWith('.') ||
    email.includes('..')
  ) {
    return false;
  }

  if ((email.match(/@/g) || []).length !== 1) {
    return false;
  }

  const parts = email.split('@');

  if (parts.length !== 2) {
    return false;
  }

  const [localPart, domain] = parts;

  if (
    !localPart ||
    !domain ||
    localPart.startsWith('.') ||
    localPart.endsWith('.')
  ) {
    return false;
  }

  const basicPattern =
    /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;

  if (!basicPattern.test(email)) {
    return false;
  }

  const domainParts = domain.split('.');

  return domainParts.every(part => {
    return (
      part.length > 0 &&
      !part.startsWith('-') &&
      !part.endsWith('-')
    );
  });
}

function isValidPhone(value) {
  const phone = clean(value);
  const digits = phone.replace(/\D/g, '');

  if (digits.length < 8 || digits.length > 15) {
    return false;
  }

  // Reject obviously fake repeated numbers.
  if (/^(\d)\1+$/.test(digits)) {
    return false;
  }

  return /^[+()\d\s.-]+$/.test(phone);
}

function isValidTimezone(value) {
  const timezone = clean(value);

  return (
    timezone === 'UTC' ||
    timezone === 'GMT' ||
    /^[A-Za-z_]+(?:\/[A-Za-z0-9_+\-]+)+$/.test(timezone)
  );
}

function safeSheetText(value) {
  const text = clean(value);

  // Prevent spreadsheet formula injection.
  if (/^[=+\-@]/.test(text)) {
    return `'${text}`;
  }

  return text;
}

const languageMap = new Map([
  ['ar', 'Arabic'],
  ['arabic', 'Arabic'],
  ['العربيه', 'Arabic'],

  ['en', 'English'],
  ['english', 'English'],
  ['الانجليزيه', 'English'],

  ['fr', 'French'],
  ['french', 'French'],
  ['francais', 'French'],
  ['الفرنسيه', 'French']
]);

const requestTypeMap = new Map([
  ['free trial', 'FREE_TRIAL'],
  ['trial', 'FREE_TRIAL'],
  ['free trial lesson', 'FREE_TRIAL'],
  ['حصه تجريبيه', 'FREE_TRIAL'],
  ['جلسه تجريبيه', 'FREE_TRIAL'],

  ['consultation', 'CONSULTATION'],
  ['استشاره', 'CONSULTATION'],

  ['callback', 'CALLBACK'],
  ['call back', 'CALLBACK'],
  ['مكالمه', 'CALLBACK'],
  ['اتصال', 'CALLBACK'],

  ['registration', 'ENROLLMENT'],
  ['enrollment', 'ENROLLMENT'],
  ['تسجيل', 'ENROLLMENT'],
  ['اشتراك', 'ENROLLMENT'],

  ['human contact', 'HUMAN_CONTACT'],
  ['human handoff', 'HUMAN_CONTACT'],
  ['التواصل مع الفريق', 'HUMAN_CONTACT']
]);

const acceptedConfirmations = new Set([
  canonical(
    'أؤكد صحة البيانات وأوافق على مشاركتها والتواصل معي'
  ),
  canonical(
    'I confirm the details are correct and consent to sharing them and being contacted'
  ),
  canonical(
    "Je confirme que les informations sont correctes et j'accepte de les partager et d'être contacté"
  ),
  canonical(
    "Je confirme que les informations sont correctes et j'accepte de les partager et d'être contactée"
  )
]);

const sessionId = clean(raw.session_id);
const parentName = clean(raw.parent_name);
const studentName = clean(raw.student_name);
const phone = clean(raw.phone);
const email = clean(raw.email).toLowerCase();
const country = clean(raw.country);
const city = clean(raw.city);
const timezone = clean(raw.timezone);
const subject = clean(raw.subject);
const grade = clean(raw.grade);
const lastSummary = clean(raw.last_summary);

const preferredLanguage =
  languageMap.get(canonical(raw.preferred_language)) || '';

const requestType =
  requestTypeMap.get(canonical(raw.request_type)) || '';

const consentGiven =
  toBoolean(raw.consent_to_contact);

const confirmed =
  toBoolean(raw.confirmed);

const confirmationMessage =
  canonical(raw.confirmation_message);

const naturalConfirmationPattern =
  /^(نعم|اجل|اوافق|موافق|اوكد|تم التاكيد|البيانات صحيحه|yes|i agree|i confirm|confirmed|oui|j accepte|je confirme)(\s|$)/;

const explicitFinalConfirmation =
  acceptedConfirmations.has(confirmationMessage) ||
  (
    consentGiven &&
    confirmed &&
    naturalConfirmationPattern.test(
      confirmationMessage
    )
  );

const validationErrors = [];

function addError(field, code) {
  validationErrors.push({
    field,
    code
  });
}

if (
  !sessionId ||
  sessionId.length < 8 ||
  sessionId.length > 150
) {
  addError('session_id', 'invalid_session_id');
}

if (!isFullName(parentName)) {
  addError('parent_name', 'invalid_full_name');
}

if (!isFullName(studentName)) {
  addError('student_name', 'invalid_full_name');
}

if (!isValidPhone(phone)) {
  addError('phone', 'invalid_phone');
}

if (!isValidEmail(email)) {
  addError('email', 'invalid_email');
}

if (!isNormalText(country)) {
  addError('country', 'invalid_country');
}

if (!isNormalText(city)) {
  addError('city', 'invalid_city');
}

if (!isValidTimezone(timezone)) {
  addError('timezone', 'invalid_timezone');
}

if (!isNormalText(subject)) {
  addError('subject', 'invalid_subject');
}

if (!isNormalText(grade, 1, 80)) {
  addError('grade', 'invalid_grade');
}

if (!preferredLanguage) {
  addError(
    'preferred_language',
    'unsupported_preferred_language'
  );
}

if (!requestType) {
  addError('request_type', 'unsupported_request_type');
}

if (
  lastSummary.length < 10 ||
  lastSummary.length > 500
) {
  addError('last_summary', 'invalid_last_summary');
}

if (!consentGiven) {
  addError(
    'consent_to_contact',
    'explicit_consent_required'
  );
}

if (!confirmed) {
  addError(
    'confirmed',
    'final_confirmation_required'
  );
}

if (!explicitFinalConfirmation) {
  addError(
    'confirmation_message',
    'confirmation_phrase_not_verified'
  );
}

const now = new Date();
const createdAt = now.toISOString();
const followUpAt =
  new Date(now.getTime() + 60 * 60 * 1000).toISOString();

const timestamp = createdAt
  .replace(/[-:.TZ]/g, '')
  .slice(0, 14);

const sessionSuffix = sessionId
  .replace(/[^A-Za-z0-9]/g, '')
  .slice(-8)
  .toUpperCase();

const leadId =
  `LEAD-${timestamp}-${sessionSuffix || 'SESSION'}`;

return [
  {
    json: {
      valid: validationErrors.length === 0,
      validation_errors: validationErrors,

      session_id: sessionId,
      lead_id: leadId,
      created_at: createdAt,
      follow_up_at: followUpAt,

      parent_name: safeSheetText(parentName),
      student_name: safeSheetText(studentName),
      phone: safeSheetText(phone),
      email,
      country: safeSheetText(country),
      city: safeSheetText(city),
      timezone,
      subject: safeSheetText(subject),
      grade: safeSheetText(grade),
      preferred_language: preferredLanguage,

      consent_to_contact:
        consentGiven ? 'YES' : 'NO',

      confirmed:
        confirmed && explicitFinalConfirmation,

      last_summary: safeSheetText(lastSummary),
      request_type: requestType,

      lead_stage: 'human_handoff_requested',
      status: 'Active',
      assigned_to: 'Unassigned',
      next_action:
        'Contact parent and arrange consultation or free trial',

      message_ar:
        validationErrors.length === 0
          ? 'تم التحقق من بيانات الطلب بنجاح.'
          : 'تعذر إرسال الطلب لأن بعض البيانات ناقصة أو غير صالحة.',

      message_en:
        validationErrors.length === 0
          ? 'The request details were validated successfully.'
          : 'The request could not be submitted because some details are missing or invalid.',

      message_fr:
        validationErrors.length === 0
          ? 'Les informations de la demande ont été validées.'
          : 'La demande ne peut pas être envoyée car certaines informations sont manquantes ou invalides.'
    }
  }
];

const data = $input.first()?.json ?? {};

return [
  {
    json: {
      success: false,
      status: 'validation_failed',

      validation_errors:
        Array.isArray(data.validation_errors)
          ? data.validation_errors
          : [],

      message_ar:
        data.message_ar ||
        'تعذر إرسال الطلب بسبب بيانات ناقصة أو غير صالحة.',

      message_en:
        data.message_en ||
        'The request could not be submitted because some details are invalid.',

      message_fr:
        data.message_fr ||
        'La demande ne peut pas être envoyée car certaines informations sont invalides.'
    }
  }
];

const payload =
  $('Validate Lead Payload').first().json ?? {};

const rows = $input
  .all()
  .map(item => item.json ?? {})
  .filter(row => {
    return (
      String(row.session_id ?? '').trim() ===
      String(payload.session_id ?? '').trim()
    );
  });

const existingCount = rows.length;
const existingRow = rows[0] ?? {};

const handoffAction =
  existingCount === 0
    ? 'created'
    : existingCount === 1
      ? 'updated'
      : 'conflict';

return [
  {
    json: {
      ...payload,

      existing_count: existingCount,

      can_upsert:
        existingCount <= 1,

      handoff_action: handoffAction,

      lead_id:
        String(existingRow.lead_id ?? '').trim() ||
        payload.lead_id,

      created_at:
        String(existingRow.created_at ?? '').trim() ||
        payload.created_at
    }
  }
];

const data = $input.first()?.json ?? {};

return [
  {
    json: {
      success: false,
      status: 'duplicate_conflict',
      error_code: 'MULTIPLE_LEADS_FOR_SESSION',

      message_ar:
        'تعذر تحديث الطلب تلقائيًا بسبب وجود تعارض في السجلات. لم يتم إنشاء سجل جديد.',

      message_en:
        'The request could not be updated automatically because conflicting records were found. No new record was created.',

      message_fr:
        'La demande ne peut pas être mise à jour automatiquement en raison de données conflictuelles. Aucun nouvel enregistrement n’a été créé.'
    }
  }
];

const data =
  $('Assess Existing Lead').first().json ?? {};

const wasUpdated =
  data.handoff_action === 'updated';

return [
  {
    json: {
      success: true,

      status:
        wasUpdated
          ? 'updated'
          : 'created',

      lead_id: data.lead_id,

      message_ar:
        wasUpdated
          ? 'تم تحديث طلبك الحالي بنجاح وإرساله إلى فريق Success Path Mentors.'
          : 'تم تسجيل طلبك بنجاح وإرساله إلى فريق Success Path Mentors.',

      message_en:
        wasUpdated
          ? 'Your existing request was updated successfully and sent to the Success Path Mentors team.'
          : 'Your request was recorded successfully and sent to the Success Path Mentors team.',

      message_fr:
        wasUpdated
          ? 'Votre demande existante a été mise à jour et transmise à l’équipe Success Path Mentors.'
          : 'Votre demande a été enregistrée et transmise à l’équipe Success Path Mentors.'
    }
  }
];
